interface Point {
    x: number;
    y: number;
}
interface Port {
    x: number;
    y: number;
    labels: string[];
}
interface PathPrimitive {
    type: "path";
    fill?: boolean;
    points: Point[];
    color: string;
    closed?: boolean;
    strokeWidth?: number;
}
interface TextPrimitive {
    type: "text";
    text: string;
    fontSize?: number;
    x: number;
    y: number;
    anchor: NinePointAnchor;
}
interface CirclePrimitive {
    type: "circle";
    x: number;
    y: number;
    radius: number;
    fill: boolean;
    color: string;
}
interface BoxPrimitive {
    type: "box";
    x: number;
    y: number;
    width: number;
    height: number;
    anchor: string;
}
type Primitive = PathPrimitive | TextPrimitive | CirclePrimitive | BoxPrimitive;
interface SchSymbol {
    primitives: Primitive[];
    center: Point;
    ports: Port[];
    size: {
        width: number;
        height: number;
    };
}
type NinePointAnchor = "top_left" | "top_right" | "bottom_left" | "bottom_right" | "center" | "middle_top" | "middle_bottom" | "middle_left" | "middle_right";

declare function getInnerSvg(symbol: SchSymbol, options?: {
    width?: number;
    height?: number;
    debug?: boolean;
}): string;
declare function getSvg(symbol: SchSymbol, options?: {
    width?: number;
    height?: number;
    debug?: boolean;
}): string;

declare function resizeSymbol(symbol: SchSymbol, newSize: {
    width?: number;
    height?: number;
}): SchSymbol;

